import { useEffect, useState } from "react";
import type { NoirEvidence, NoirOperationRecord } from "@agentpay/shared";

/**
 * Recorded Noir Testnet run (operator journal snapshot, Nov 6 2026). The journal
 * lives on the operator's machine, so the web shows this static snapshot, never
 * live state. Regenerated by the operator after a new run; contains no secrets.
 */
export const EVIDENCE_PATH = "evidence/snapp-demo-001.json";

export function useNoirEvidence() {
  const [data, setData] = useState<NoirEvidence | null>(null);
  const [error, setError] = useState("");
  const [attempt, setAttempt] = useState(0);
  useEffect(() => {
    const ctrl = new AbortController();
    setError("");
    fetch(`${import.meta.env.BASE_URL}${EVIDENCE_PATH}`, { signal: ctrl.signal })
      .then((r) => {
        if (!r.ok) throw new Error(`Snapshot returned ${r.status}`);
        return r.json() as Promise<NoirEvidence>;
      })
      .then(setData)
      .catch((e: unknown) => !ctrl.signal.aborted && setError(e instanceof Error ? e.message : String(e)));
    return () => ctrl.abort();
  }, [attempt]);
  return { data, error, loading: !data && !error, retry: () => setAttempt((n) => n + 1) };
}

export const operationLabel: Record<NoirOperationRecord["kind"], { step: string; what: string; signer: "owner" | "agent" | "merchant" }> = {
  device: { step: "registerDevice", what: "Owner registers the signing device", signer: "owner" },
  policy: { step: "registerAgent", what: "Owner sets the agent's spending policy", signer: "owner" },
  fund: { step: "fundEscrow", what: "Owner funds the escrow", signer: "owner" },
  authorize: { step: "authorize", what: "Agent authorizes the approved item", signer: "agent" },
  claim: { step: "claim", what: "Merchant claims pending funds", signer: "merchant" },
};

/** Seconds between two ISO timestamps, or null when either is missing. */
export function secondsBetween(a?: string, b?: string) {
  if (!a || !b) return null;
  const d = (Date.parse(b) - Date.parse(a)) / 1000;
  return Number.isFinite(d) && d >= 0 ? Math.round(d) : null;
}

export const phtTime = (iso: string) =>
  new Date(iso).toLocaleTimeString("en-PH", {
    timeZone: "Asia/Manila",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
  }) + " PHT";

export const phtDay = (iso: string) =>
  new Date(iso).toLocaleDateString("en-PH", { timeZone: "Asia/Manila", dateStyle: "medium" });
